	@Test
	void completedReplayKeepsDictionaryAliveForAcceptedReaderAfterDatasetClose() throws Exception {
		NativeExecutionContext context = new NativeExecutionContext();
		LmdbQueryMemoryManager memory = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
		try (var dataset = NativeQuerySourceAccess.openExplicitDataset((LmdbStore) repository.getSail());
				var ledger = memory.openQuery();
				context) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			long subject = firstSubject(source);
			String expected = source.lazyValue(subject).stringValue();
			NativeResultRow.Schema schema = new NativeResultRow.Schema("term");
			try (NativeResultReplay replay = new NativeResultReplay(schema, context, context.cancellation(), ledger,
					16L << 10).resolvingStoreTermsWith(source)) {
				for (int i = 0; i < 512; i++) {
					replay.append(new NativeResultRow(schema,
							new NativeResultCell[] { NativeResultCell.term(source.lazyValue(subject)) }));
				}
				assertTrue(replay.spilled(), "the dictionary lifetime is needed by the spill reader");
				replay.finish();
				try (NativeResultCursor reader = replay.cursor()) {
					replay.close();
					context.close();
					dataset.close();
					try (var workers = Executors.newSingleThreadExecutor()) {
						workers.submit(() -> {
							for (int i = 0; i < 512; i++) {
								LmdbValue term = assertInstanceOf(LmdbValue.class, reader.next().cell("term").value());
								assertEquals(subject, term.getInternalID());
								assertEquals(expected, ((Value) term).stringValue());
							}
							assertNull(reader.next());
							return null;
						}).get();
					}
				}
			}
			assertEquals(0L, memory.usedBytes());
		}
	}

