	@Test
	void sameStoreDifferentRevisionIsEncodedLexically() throws Exception {
		NativeExecutionContext context = new NativeExecutionContext();
		LmdbQueryMemoryManager memory = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
		try (var dataset = NativeQuerySourceAccess.openExplicitDataset((LmdbStore) repository.getSail());
				var ledger = memory.openQuery();
				context) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			long subject = firstSubject(source);
			LmdbValue current = assertInstanceOf(LmdbValue.class, source.lazyValue(subject));
			String spelling = EX + "different-revision-value";
			LmdbIRI stale = new LmdbIRI(new ValueStoreRevision.Default(current.getValueStoreRevision().getValueStore()),
					spelling, subject);
			NativeResultRow.Schema schema = new NativeResultRow.Schema("term");
			try (NativeResultReplay replay = new NativeResultReplay(schema, context, context.cancellation(), ledger,
					16L << 10).resolvingStoreTermsWith(source)) {
				for (int i = 0; i < 64; i++) {
					Value filler = SimpleValueFactory.getInstance().createIRI(EX, "filler" + i + "x".repeat(512));
					replay.append(
							new NativeResultRow(schema, new NativeResultCell[] { NativeResultCell.term(filler) }));
				}
				assertTrue(replay.spilled());
				replay.append(new NativeResultRow(schema, new NativeResultCell[] { NativeResultCell.term(current) }));
				replay.append(new NativeResultRow(schema, new NativeResultCell[] { NativeResultCell.term(stale) }));
				replay.finish();
				try (NativeResultCursor reader = replay.cursor()) {
					for (int i = 0; i < 64; i++) {
						reader.next();
					}
					assertEquals(subject, assertInstanceOf(LmdbValue.class, reader.next().cell("term").value())
							.getInternalID());
					Value restored = reader.next().cell("term").value();
					assertFalse(restored instanceof LmdbValue, "a different dictionary revision must not reuse an ID");
					assertEquals(spelling, restored.stringValue());
					assertNull(reader.next());
				}
			}
			assertEquals(0L, memory.usedBytes());
		}
	}

